WITH store_summary AS (SELECT store_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(channel))) AS channel_values, SUM(CASE WHEN channel = 'store' THEN shipping_fee ELSE 0 END) AS store_shipping_fee FROM orders GROUP BY store_id) SELECT s.id, s.region, ss.channel_values, ss.store_shipping_fee FROM stores s INNER JOIN store_summary ss ON s.id = ss.store_id WHERE ss.store_shipping_fee > 29 ORDER BY s.id DESC;
